mapper.select:
SELECT 
  FROM fnd30_opr
       LEFT OUTER JOIN apr01_appr ON fnd30_appr_id = apr01_appr_id
 WHERE 1=1
   AND fnd30_company_id = #{companyId}
   AND fnd30_opr_cd     = #{oprCode}
   AND fnd30_demand_date BETWEEN #{startDate} AND #{closeDate}
   AND UPPER((fnd30_lead_manager||fnd30_item_nm)) LIKE UPPER(#{searchText})
 ORDER BY fnd30_demand_date desc
        , fnd30_item_nm collate "ko_KR.utf8" asc

SELECT 
  FROM fnd30_opr
       LEFT OUTER JOIN apr01_appr ON fnd30_appr_id = apr01_appr_id
 WHERE fnd30_opr_id     = #{oprId}
   AND fnd30_company_id = #{companyId}

mapper.insert:
INSERT INTO fnd30_opr
       ( fnd30_opr_id, fnd30_company_id, fnd30_opr_cd, fnd30_opr_date, fnd30_demand_date, fnd30_item_nm, fnd30_lead_manager
       , fnd30_demand_period, fnd30_market, fnd30_price_bracket, fnd30_price, fnd30_price_accept_yn, fnd30_lock_period
       , fnd30_note, fnd30_cancel_yn, fnd30_pay_date )
VALUES ( #{oprId}, #{companyId}, '02', #{r.demandDate}, #{r.demandDate}, #{r.itemName}, #{r.leadManager}
       , #{r.demandPeriod}, #{r.market}, #{r.priceBracket}, #{r.price}
       , CASE WHEN #{r.priceAcceptYn} THEN 'true' ELSE 'false' END, #{r.lockPeriod}
       , #{r.note}, CASE WHEN #{r.cancelYn} THEN 'true' ELSE 'false' END, #{r.payDate} )

